// Some portions generated by Codex
package org.eclipse.rdf4j.federated.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.Dataset;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.ActiveGraphQueryEvaluationContext;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.QueryEvaluationContext;
import org.eclipse.rdf4j.query.impl.BlankNodeAllocationScope;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.eclipse.rdf4j.query.impl.SimpleDataset;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class DatasetQueryEvaluationContextTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void datasetWrappersShareAllocationAndSolutionState(boolean explicitProjectionScope) {
		BlankNodeAllocationScope allocation = new BlankNodeAllocationScope("dataset-context-", id -> false);
		QueryEvaluationContext delegate;
		try (var ignored = allocation.activate()) {
			delegate = new QueryEvaluationContext.Minimal((Dataset) null);
		}
		SimpleDataset dataset = new SimpleDataset();
		dataset.addDefaultGraph(VF.createIRI("urn:dataset"));
		QueryEvaluationContext wrapper = explicitProjectionScope
				? new DatasetQueryEvaluationContext(delegate, dataset, true)
				: new DatasetQueryEvaluationContext(delegate, dataset);

		assertSame(allocation, wrapper.getBlankNodeAllocationScope());
		assertSame(dataset, wrapper.getDataset());
		assertEquals(explicitProjectionScope, wrapper.hasEnclosingProjection());

		wrapper.getBlankNodeAllocationScope().reserve("dataset-context-0");
		assertEquals("dataset-context-1", delegate.getBlankNodeAllocationScope().createBNode(VF).getID());
		BNode labelled = delegate.getOrCreateBNode("shared", EmptyBindingSet.getInstance(), VF);
		assertSame(labelled, wrapper.getOrCreateBNode("shared", EmptyBindingSet.getInstance(), VF));
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void nestedGraphAndDatasetWrappersShareAllocationState(boolean datasetOutsideGraph) {
		QueryEvaluationContext delegate = new QueryEvaluationContext.Minimal((Dataset) null);
		QueryEvaluationContext.ActiveGraph graph = new QueryEvaluationContext.ActiveGraph(VF.createIRI("urn:graph"),
				null);
		QueryEvaluationContext wrapper = datasetOutsideGraph
				? new DatasetQueryEvaluationContext(new ActiveGraphQueryEvaluationContext(delegate, graph), null, true)
				: new ActiveGraphQueryEvaluationContext(new DatasetQueryEvaluationContext(delegate, null, true), graph);

		assertSame(delegate.getBlankNodeAllocationScope(), wrapper.getBlankNodeAllocationScope());
		assertSame(graph, wrapper.getActiveGraph());
		BNode labelled = delegate.getOrCreateBNode("shared", EmptyBindingSet.getInstance(), VF);
		assertSame(labelled, wrapper.getOrCreateBNode("shared", EmptyBindingSet.getInstance(), VF));
	}
}
